'use strict';
for(const p of POLICY_DATA){const section=document.createElement('section');section.className='source-item';const h=document.createElement('h2');h.textContent=`${p.name} · ${p.policy}`;const meta=document.createElement('p');meta.textContent=`${p.party} · ${p.year} · ${p.stage} (발표 당시 기준)`;const links=document.createElement('p');for(const [label,url] of [[p.sourceLabel,p.source],['관련 뉴스',p.news],['관련 법령 검색: '+p.law,'https://www.law.go.kr/LSW/unSc.do?query='+encodeURIComponent(p.law)]]){const a=document.createElement('a');a.textContent=label+' ↗';a.href=url;a.target='_blank';a.rel='noopener noreferrer';links.append(a,document.createElement('br'));}section.append(h,meta,links);if(p.sourceNote){const note=document.createElement('p');note.textContent=p.sourceNote;section.append(note);}document.querySelector('#sources').append(section);}
